mapper.select:
WITH RECURSIVE parent_categories AS ( -- 基础查询：找到所有当前分类 SELECT id, name, parent_id, id AS root_id -- 保留根节点id FROM courses_type WHERE id IN
#{id}
UNION ALL
-- 递归查询：找到父级分类 SELECT ct.id, ct.name, ct.parent_id, pc.root_id -- 保留根节点id FROM courses_type ct INNER JOIN parent_categories pc ON ct.id = pc.parent_id ) SELECT pc1.root_id AS id, GROUP_CONCAT(pc1.name ORDER BY pc1.id DESC SEPARATOR '/') AS name FROM parent_categories pc1 GROUP BY pc1.root_id;
